import os
import asyncio
import uuid
import json
import sqlite3
import httpx
import uvicorn
import modal
from fastapi import FastAPI, WebSocket, Request, HTTPException
from fastapi.responses import HTMLResponse
from pydantic import BaseModel
from typing import List, Dict, Optional

app = FastAPI()

class ProjectCreate(BaseModel):
    name: str
    language: str

class KVStore:
    def __init__(self, db_path="internal.db"):
        self.conn = sqlite3.connect(db_path, check_same_thread=False)
        self.cursor = self.conn.cursor()
        self.cursor.execute("CREATE TABLE IF NOT EXISTS storage (key TEXT PRIMARY KEY, value TEXT)")
        self.conn.commit()

    def set(self, key: str, value: str):
        self.cursor.execute("INSERT OR REPLACE INTO storage (key, value) VALUES (?, ?)", (key, value))
        self.conn.commit()

    def get(self, key: str):
        self.cursor.execute("SELECT value FROM storage WHERE key = ?", (key,))
        row = self.cursor.fetchone()
        return row[0] if row else None

db = KVStore()

@app.get("/", response_class=HTMLResponse)
async def index():
    with open("index.html", "r", encoding="utf-8") as f:
        return f.read()

@app.post("/api/projects")
async def create_project(proj: ProjectCreate):
    project_id = str(uuid.uuid4())
    project_data = {
        "id": project_id,
        "name": proj.name,
        "language": proj.language,
        "status": "provisioning"
    }
    db.set(f"project:{project_id}", json.dumps(project_data))
    return project_data

@app.websocket("/ws/ide/{project_id}")
async def ide_websocket(websocket: WebSocket, project_id: str):
    await websocket.accept()
    try:
        while True:
            data = await websocket.receive_json()
            if data["type"] == "sync":
                db.set(f"code:{project_id}", data["content"])
                await websocket.send_json({"type": "ack", "status": "saved"})
    except Exception:
        await websocket.close()

if __name__ == "__main__":
    uvicorn.run(app, host="0.0.0.0", port=8000)
