import os
import subprocess
import json

class ContainerOrchestrator:
    def __init__(self):
        self.nix_path = "/nix/var/nix/profiles/default/bin/nix-shell"

    def create_runtime_env(self, project_id: str, language: str):
        nix_config = self._get_nix_config(language)
        path = f"/containers/{project_id}"
        os.makedirs(path, exist_ok=True)
        with open(f"{path}/shell.nix", "w") as f:
            f.write(nix_config)
        return path

    def _get_nix_config(self, language: str):
        pkgs = {
            "zig": "zig",
            "inko": "inko",
            "scopes": "scopes",
            "lobster": "lobster",
            "racket": "racket",
            "vlang": "vlang",
            "beef": "beef",
            "python": "python311"
        }
        pkg = pkgs.get(language, "python311")
        return f"{{ pkgs ? import <nixpkgs> {{}} }}: pkgs.mkShell {{ buildInputs = [ pkgs.{pkg} ]; }}"

    def snapshot_filesystem(self, project_id: str):
        src = f"/containers/{project_id}"
        dest = f"/snapshots/{project_id}_{int(os.times()[4])}"
        subprocess.run(["cp", "-a", src, dest], check=True)
        return dest
