import os
import httpx
import json

class AutonomousDeveloper:
    def __init__(self):
        self.grok_url = "api.x.ai"
        self.claude_url = "runtime.bedrock.us-east-1.amazonaws.com"
        self.glm_url = "api.cerebras.ai"
        self.keys = {
            "grok": os.getenv("GROK_API_KEY"),
            "claude": os.getenv("AWS_SECRET_KEY"),
            "glm": os.getenv("CEREBRAS_API_KEY")
        }

    async def multi_inference_generate(self, prompt: str, language: str):
        async with httpx.AsyncClient() as client:
            arch_resp = await client.post(
                self.claude_url,
                headers={"Authorization": f"Bearer {self.keys['claude']}"},
                json={"prompt": f"Design architecture for: {prompt}", "max_tokens": 4096}
            )
            architecture = arch_resp.json()["completion"]

            code_resp = await client.post(
                self.glm_url,
                headers={"Authorization": f"Bearer {self.keys['glm']}"},
                json={"messages": [{"role": "user", "content": f"Write {language} code for {architecture}"}]}
            )
            code = code_resp.json()["choices"][0]["message"]["content"]

            reflection_resp = await client.post(
                self.grok_url,
                headers={"Authorization": f"Bearer {self.keys['grok']}"},
                json={"messages": [{"role": "user", "content": f"Review and fix this {language} code:\n{code}"}]}
            )
            return reflection_resp.json()["choices"][0]["message"]["content"]
