        self.conn = sqlite3.connect(self.db_path, check_same_thread=False)
        self.conn.execute("PRAGMA journal_mode=WAL")
        self.conn.execute("PRAGMA synchronous=NORMAL")
        self.cursor = self.conn.cursor()
        self.cursor.execute("CREATE TABLE IF NOT EXISTS storage (key TEXT PRIMARY KEY, value TEXT)")
        self.conn.commit()

    async def set(self, key: str, value: str):
        async with self._lock:
            try:
                self.cursor.execute("INSERT OR REPLACE INTO storage (key, value) VALUES (?, ?)", (key, value))
                self.conn.commit()
            except sqlite3.Error as e:
                print(f"Database error: {e}")

    async def get(self, key: str):
        async with self._lock:
            self.cursor.execute("SELECT value FROM storage WHERE key = ?", (key,))
            row = self.cursor.fetchone()
            return row[0] if row else None

    def close(self):
        self.conn.close()

db = KVStore()

@asynccontextmanager
async def lifespan(app: FastAPI):
    yield
    db.close()

app = FastAPI(lifespan=lifespan)

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_methods=["*"],
    allow_headers=["*"],
)

@app.get("/", response_class=HTMLResponse)
async def index():
