        with open("index.html", "r", encoding="utf-8") as f:
            return f.read()
    except FileNotFoundError:
        raise HTTPException(status_code=404, detail="Frontend file missing")

@app.post("/api/projects", status_code=status.HTTP_201_CREATED)
async def create_project(proj: ProjectCreate):
    project_id = str(uuid.uuid4())
    project_data = {
        "id": project_id,
        "name": proj.name,
        "language": proj.language,
        "status": "active",
        "created_at": os.times()[4]
    }
    await db.set(f"project:{project_id}", json.dumps(project_data))
    return project_data

@app.websocket("/ws/ide/{project_id}")
async def ide_websocket(websocket: WebSocket, project_id: str):
    project_exists = await db.get(f"project:{project_id}")
    if not project_exists:
        await websocket.close(code=status.WS_1008_POLICY_VIOLATION)
        return

    await websocket.accept()
    try:
        while True:
            raw_data = await websocket.receive_text()
            data = json.loads(raw_data)

            if not isinstance(data, dict) or "type" not in data:
                continue

            if data["type"] == "sync" and "content" in data:
                if isinstance(data["content"], str) and len(data["content"]) < 1000000:
                    await db.set(f"code:{project_id}", data["content"])
                    await websocket.send_json({"type": "ack", "status": "saved", "ts": os.times()[4]})
    except (json.JSONDecodeError, KeyError, Exception) as e:
        print(f"WS Error: {e}")
    finally:
        try:
            await websocket.close()
        except:
            pass

