class ContainerOrchestrator:
    def __init__(self):
        self.base_dir = os.path.abspath("./containers")
        self.snap_dir = os.path.abspath("./snapshots")
        os.makedirs(self.base_dir, exist_ok=True)
        os.makedirs(self.snap_dir, exist_ok=True)

    def create_runtime_env(self, project_id: str, language: str):
        safe_id = "".join(c for c in project_id if c.isalnum() or c == "-")
        path = os.path.join(self.base_dir, safe_id)
        os.makedirs(path, exist_ok=True)

        nix_config = self._get_nix_config(language)
        with open(os.path.join(path, "shell.nix"), "w", encoding="utf-8") as f:
            f.write(nix_config)
        return path

    def _get_nix_config(self, language: str):
        pkgs = {
            "zig": "zig",
            "inko": "inko",
            "scopes": "scopes",
            "lobster": "lobster",
            "racket": "racket",
            "vlang": "vlang",
            "beef": "beef",
            "python": "python311"
        }
        pkg = pkgs.get(language, "python311")
        return f"""
{{ pkgs ? import (fetchTarball "github.com") {{}} }}:
pkgs.mkShell {{
  buildInputs = [ pkgs.{pkg} ];
  shellHook = ''
    echo "Environment for {language} ready"
  '';
}}
"""

    def snapshot_filesystem(self, project_id: str):
        safe_id = "".join(c for c in project_id if c.isalnum() or c == "-")
        src = os.path.join(self.base_dir, safe_id)
        if not os.path.exists(src):
            return None

        timestamp = int(os.times()[4] * 1000)
        dest = os.path.join(self.snap_dir, f"{safe_id}_{timestamp}")
        shutil.copytree(src, dest)
        return dest
