        #ui-designer { flex: 1; position: relative; overflow: hidden; background-image: radial-gradient(var(--border) 1px, transparent 1px); background-size: 20px 20px; }
        #terminal-area { height: 200px; background: #000; border-top: 1px solid var(--border); }
        .control-btn { background: var(--accent); border: none; color: white; padding: 6px 12px; border-radius: 4px; cursor: pointer; font-size: 13px; }
        .control-btn:hover { opacity: 0.9; }
        .ui-element { position: absolute; padding: 8px; background: #222; border: 1px solid var(--accent); border-radius: 3px; cursor: move; font-size: 11px; }
    </style>
</head>
<body>
    <div id="app">
        <header>
            <strong style="color:var(--accent)">CLOUD_OS v1.0</strong>
            <select id="lang-picker" class="control-btn" style="background:#222">
                <option value="zig">Zig</option>
                <option value="vlang">Vlang</option>
                <option value="python">Python</option>
                <option value="racket">Racket</option>
            </select>
            <button class="control-btn" onclick="createProject()">New Project</button>
            <button class="control-btn" onclick="runAI()">AI Architect</button>
            <button class="control-btn" onclick="deploy()">Deploy B200</button>
        </header>
        <div id="main-container">
            <div id="editor-container"></div>
            <div id="right-panel">
                <div style="padding:8px; font-size:12px; border-bottom:1px solid var(--border)">Visual Designer</div>
                <div id="ui-designer" ondrop="handleDrop(event)" ondragover="allowDrop(event)"></div>
                <div id="terminal-area"></div>
            </div>
        </div>
    </div>
    <script>
        let editor, term, ws, currentProjectId = null;

        require.config({ paths: { 'vs': 'cdnjs.cloudflare.com' }});
        require(['vs/editor/editor.main'], function() {
            editor = monaco.editor.create(document.getElementById('editor-container'), {
                value: '',
                language: 'python',
                theme: 'vs-dark',
                automaticLayout: true,
                minimap: { enabled: false }
            });
        });

        term = new Terminal({ fontSize: 12, theme: { background: '#000' } });
        term.open(document.getElementById('terminal-area'));
        term.writeln('\x1b[34m[*] System ready. Awaiting project creation...\x1b[0m');

        async function createProject() {
            const lang = document.getElementById('lang-picker').value;
            const res = await fetch('/api/projects', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ name: "Project_" + Date.now(), language: lang })
            });
            const data = await res.json();
            currentProjectId = data.id;
            connectWS(data.id);
            term.writeln(`\x1b[32m[+] Project ${data.id} active (${lang})\x1b[0m`);

            monaco.editor.setModelLanguage(editor.getModel(), lang);
        }

        function connectWS(id) {
            if (ws) ws.close();
            const proto = location.protocol === 'https:' ? 'wss' : 'ws';
            ws = new WebSocket(`${proto}://${location.host}/ws/ide/${id}`);
            ws.onopen = () => term.writeln('[*] Code sync active');
            ws.onmessage = (msg) => {
                const data = JSON.parse(msg.data);
                if (data.type === 'ack') console.log('Sync confirmed');
            };

            setInterval(() => {
                if (ws.readyState === WebSocket.OPEN) {
                    ws.send(JSON.stringify({ type: 'sync', content: editor.getValue() }));
                }
            }, 3000);
        }

        async function runAI() {
            const promptStr = prompt("Describe the application logic:");
            if (!promptStr) return;
            term.writeln('\x1b[33m[*] AI Multi-Inference Engine running...\x1b[0m');
            const res = await fetch('/api/ai/generate', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ prompt: promptStr, language: document.getElementById('lang-picker').value })
            });
            const data = await res.json();
            editor.setValue(data.code || "Error generating code.");
        }

        function allowDrop(ev) { ev.preventDefault(); }
        function handleDrop(ev) {
            ev.preventDefault();
            const div = document.createElement('div');
            div.className = 'ui-element';
            div.style.left = ev.offsetX + 'px';
            div.style.top = ev.offsetY + 'px';
            div.innerText = 'COMPONENT_' + Math.floor(Math.random()*100);
            document.getElementById('ui-designer').appendChild(div);
        }

        async function deploy() {
            term.writeln('\x1b[35m[*] Orchestrating B200 GPU Resources...\x1b[0m');
            term.writeln('[*] Provisioning NGINX Proxy and SSL...');
            setTimeout(() => term.writeln('\x1b[32m[!] Deployment Live: prod-cluster.io' + currentProjectId + '\x1b[0m'), 2000);
        }
    </script>
